sec='chapter-12-review'
def review(num,fields,why,limited=False,suffix=''):put(sec,num,fields,why,limited,suffix)
def concept(num,fields,why):review(num,fields,why,True,'-concept-check-1')
concept(1,c('Distinction','A scalar has magnitude alone; a vector has magnitude and direction','Both have only magnitude','Only scalars have direction'),'The zero vector has zero magnitude and no distinguished direction.')
concept(2,[c('Geometric addition','Head-to-tail triangle rule or parallelogram diagonal','Multiply the arrow lengths','Always subtract directions'),c('Algebraic addition','Add corresponding components','Multiply corresponding components','Add only magnitudes')],'Vector displacement combines componentwise and by successive arrows.')
concept(3,[c('Geometric scaling','Length scales by|c|; direction is preserved ifc>0 and reversed ifc<0; c=0 gives zero','Negative c leaves direction unchanged','Length always scales by c without absolute value'),c('Components','ca=(ca₁,ca₂,ca₃)','ca=(a₁+c,a₂+c,a₃+c)','ca=(c,c,c)')],'Scalar multiplication distributes to each coordinate.')
concept(4,c('Displacement P to Q','Q−P','P−Q','P+Q'),'Terminal minus initial coordinates gives the directed displacement.')
concept(5,[c('Lengths and angle','a·b=|a||b|cosθ','a·b=|a||b|sinθ','a·b=|a|+|b|'),c('Components','a·b=Σaᵢbᵢ','a·b=(a₁b₁,a₂b₂,a₃b₃)','a·b=Σ(aᵢ+bᵢ)')],'The dot product is scalar and records the parallel component.')
concept(6,c('Uses','Angles, orthogonality, scalar/vector projections, and work','A vector perpendicular to two vectors directly','Only adding forces'),'The cosine formula and projection formula supply these applications.')
concept(7,[c('Scalar projection','compₐb=(a·b)/|a|','compₐb=(a·b)/|b|','compₐb=|a×b|'),c('Vector projection','projₐb=(a·b)a/|a|²','projₐb=(a·b)b/|b|²','projₐb=a+b')],'For nonzero a the vector projection is the signed scalar projection times a/|a|. It lies along a and the residual is perpendicular to a.')
concept(8,[c('Magnitude and direction','|a×b|=|a||b|sinθ, perpendicular to both by the right-hand rule','Magnitude uses cosθ and direction is parallel to a','Always the zero vector'),c('Components','(a₂b₃−a₃b₂,a₃b₁−a₁b₃,a₁b₂−a₂b₁)','(a₁b₁,a₂b₂,a₃b₃)','(a₂b₃+a₃b₂,a₃b₁+a₁b₃,a₁b₂+a₂b₁)')],'The cyclic component formula fixes the right-hand orientation.')
concept(9,c('Uses','Normals, areas, torque, and scalar-triple-product volume','Scalar work directly','Adding vector lengths'),'Cross products encode oriented area and perpendicular directions.')
concept(10,[c('(a) Parallelogram area','|a×b|','a·b','|a|+|b|'),c('(b) Parallelepiped volume','|a·(b×c)|','|a×b|+|c|','a·b·c')],'Area is base times perpendicular height; volume is base area times perpendicular third-edge height.')
concept(11,c('Plane normal','Cross two nonparallel vectors in the plane, or read(a,b,c) from ax+by+cz=d','Choose any vector in the plane','Add any two plane points'),'A normal is perpendicular to all tangent directions.')
concept(12,c('Acute plane angle','arccos(|n₁·n₂|/(|n₁||n₂|))','arcsin((n₁·n₂)/(|n₁||n₂|))','The angle between any two points'),'The smaller angle between the normals equals the acute plane angle.')
concept(13,[c('Vector equation','r=r₀+tv, v≠0','r=r₀+t','r·v=0'),c('Parametric equations','x=x₀+tv₁, y=y₀+tv₂, z=z₀+tv₃','x=x₀, y=y₀, z=z₀ only','x=y=z=0'),c('Symmetric equations','(x−x₀)/v₁=(y−y₀)/v₂=(z−z₀)/v₃; ifvᵢ=0 replace that ratio by its fixed-coordinate equation','x/v₁+y/v₂+z/v₃=1','x−x₀=y−y₀=z−z₀ for every line')],'Eliminate the common parameter only for nonzero direction components.')
concept(14,[c('Vector equation','n·(r−r₀)=0, n≠0','r=r₀+tn only','n×r=0'),c('Scalar equation','a(x−x₀)+b(y−y₀)+c(z−z₀)=0','x=x₀,y=y₀,z=z₀','x²+y²+z²=1')],'A point lies in the plane exactly when its displacement from a fixed plane point is orthogonal to the normal.')
concept(15,[c('(a) Parallel vectors','Nonzero vectors are scalar multiples; equivalently their cross product is zero in R³','Their dot product is zero','Their magnitudes are equal'),c('(b) Perpendicular vectors','Their dot product is zero','Their sum is zero','Their cross product is zero'),c('(c) Parallel planes','Their nonzero normals are proportional','Their normals are perpendicular','They contain the same point')],'Handle zero-vector direction conventions separately; plane normals must be nonzero.')
concept(16,[c('(a) Collinear points','(Q−P)×(R−P)=0','(Q−P)·(R−P)=0','Equal distances are required'),c('(b) Coplanar points','(Q−P)·[(R−P)×(S−P)]=0','All pairwise distances equal','All coordinate sums zero')],'Cross-product area and scalar-triple-product volume detect the relevant degeneracy.')
concept(17,[c('(a) Point to line r=q+tv','|(p−q)×v|/|v|','|(p−q)·v|/|v|','|p−q| always'),c('(b) Point to plane n·r=d','|n·p−d|/|n|','|n·p+d|','|p|'),c('(c) Two lines','Nonparallel: |(q−p)·(u×v)|/|u×v|; parallel: point-to-line distance; intersecting:0','Always |p−q|','Always0')],'Use perpendicular heights, treating parallel directions separately because their cross product vanishes.')
concept(18,c('Traces','Intersections with coordinate-parallel planes, found by fixing one coordinate','Only intersections with axes','The gradient vector'),'Substitute x=k,y=k,or z=k to obtain the corresponding planar curve.')
concept(19,[c('Ellipsoid','x²/a²+y²/b²+z²/c²=1','x²/a²+y²/b²−z²/c²=1','z=x+y'),c('Elliptic cone','x²/a²+y²/b²=z²/c²','x²/a²+y²/b²+z²/c²=1','z=x²+y²+1'),c('Elliptic paraboloid','z/c=x²/a²+y²/b²','z/c=x²/a²−y²/b²','z²/c²=x²/a²+y²/b²'),c('Hyperbolic paraboloid','z/c=x²/a²−y²/b²','z/c=x²/a²+y²/b²','x²+y²+z²=1'),c('One-sheet hyperboloid','x²/a²+y²/b²−z²/c²=1','−x²/a²−y²/b²+z²/c²=1','x²/a²+y²/b²+z²/c²=1'),c('Two-sheet hyperboloid','−x²/a²−y²/b²+z²/c²=1','x²/a²+y²/b²−z²/c²=1','x²/a²+y²/b²+z²/c²=1')],'Take positive axis scales; rotations, translations, and axis permutations produce equivalent orientations.')
truths=[False,False,False,False,True,False,True,True,True,True,True,False,True,True,False,False,False,False,False,False,True,True]
reasons=['Dot product is a scalar sum, not a component vector.','u=i,v=−i gives0 on the left and2 on the right.','u=i,v=j gives0 versus1.','u=v=i gives0 versus1.','Real multiplication commutes in the component sum.','i×j=k but j×i=−k.','Reversing order negates the vector but preserves its norm.','A scalar factors out of the dot-product sum.','Each cross-product component is linear in the first input.','Distribute in the first cross-product input.','Both sides are the same scalar triple-product determinant.','Take u=i,v=i,w=j: left=−j and right=0.','The cross product is perpendicular to either input.','Distribute and use v×v=0.','(3,−1,2) is half the plane normal, hence perpendicular to the plane.','A nondegenerate single linear equation defines a plane, not a line.','The free z-coordinate makes a circular cylinder.','The free z-coordinate makes a parabolic cylinder.','i·j=0 with both vectors nonzero.','i×i=0 with both vectors nonzero.','The identity|u×v|²+(u·v)²=|u|²|v|² forces a zero magnitude.','This is Cauchy–Schwarz:|cosθ|≤1, with zero cases immediate.']
for j,(tr,why) in enumerate(zip(truths,reasons),1):review(j,c('Truth value','True' if tr else 'False','False' if tr else 'True'),why,True,'-true-false-quiz-2')
review(1,[c('(a) Sphere','(x+1)²+(y−2)²+(z−1)²=69','(x+1)²+(y−2)²+(z−1)²=49','x²+y²+z²=69'),c('(b) yz trace','x=0,(y−2)²+(z−1)²=68','x=0,(y−2)²+(z−1)²=69','Empty'),*vec('(c) Center',(4,-1,-3)),n('(c) Radius',5)],'Squared radius in(a) is7²+(−4)²+2²=69. Setx=0 for(b). Complete all three squares for(c).')
review(2,[c('(a) a+b','Arrow from the tail of a to the head of b in the displayed head-to-tail configuration','Arrow from head of b to tail of a','Vector a alone'),c('(b) a−b','Place −b at the head of a, then join initial tail to final head','Place b at the head of a','Reverse a only'),c('(c) a/2','Same direction as a and half its length','Opposite direction, same length','Twice its length'),c('(d) 2a+b','Two successive copies of a followed by b','a followed by two copies of b','Reverse both arrows')],'Use the displayed arrow orientation and head-to-tail addition; construction selections do not evaluate the finished drawing.',True)
review(3,[n('u·v',3*s.sqrt(2)),n('|u×v|',3*s.sqrt(2)),c('Cross-product direction','Out of the page','Into the page','In the page')],'Both magnitudes use2·3 and45°; rotation from u to v is counterclockwise.')
