review(4,[*vec('(a) 2a+3b',2*a+3*b),n('(b) |b|',b.norm()),n('(c) a·b',a.dot(b)),*vec('(d) a×b',a.cross(b)),n('(e) |b×c|',b.cross(d).norm()),n('(f) a·(b×c)',a.dot(b.cross(d))),*vec('(g) c×c',(0,0,0)),*vec('(h) a×(b×c)',a.cross(b.cross(d))),n('(i) compₐb',a.dot(b)/a.norm()),*vec('(j) projₐb',a.dot(b)/a.dot(a)*a),n('(k) Angle',float(s.acos(a.dot(b)/(a.norm()*b.norm())))*180/math.pi,'degrees',.51)],'Compute each vector operation in its displayed order; normalize by a, not b, for projection of b onto a.')
